from datetime import datetime, timedelta


def next_fire(expr, after):
    """Return the first naive datetime STRICTLY after `after` (a naive datetime) that matches cron expression `expr`.
    Results always have second == 0 and microsecond == 0.

    `expr` has exactly 5 whitespace-separated fields: minute (0-59), hour (0-23), day-of-month (1-31),
    month (1-12), day-of-week (0-7, where both 0 and 7 mean Sunday, 1 = Monday ... 6 = Saturday).
    Each field is a comma-separated list of items. An item is "*" (the whole field range), "N", or "A-B" (A <= B),
    optionally followed by "/S" (S >= 1): take every S-th value of the item starting at its first value.
    "*/S" starts at the field minimum and "N/S" means N through the field maximum in steps of S.

    Day matching: a field is "unrestricted" only if it is exactly "*". If both day-of-month and day-of-week are
    restricted, a day matches when EITHER matches; otherwise both must match.

    Empty items, out-of-range values, A > B, S < 1, non-digit characters, or a wrong number of fields raise
    ValueError. If the expression has no match within 3000 days after `after` (e.g. "0 0 30 2 *"), raise ValueError.
    """
    def parse_field(field_str, min_val, max_val):
        is_star = (field_str == '*')
        values = set()
        for item in field_str.split(','):
            if not item:
                raise ValueError("Empty item")
            step = 1
            if '/' in item:
                base, step_str = item.split('/', 1)
                if not step_str.isdigit() or int(step_str) < 1:
                    raise ValueError("Invalid step")
                step = int(step_str)
            else:
                base = item

            if base == '*':
                start, end = min_val, max_val
            elif '-' in base:
                parts = base.split('-', 1)
                if len(parts) != 2 or not parts[0].isdigit() or not parts[1].isdigit():
                    raise ValueError("Invalid range")
                start, end = int(parts[0]), int(parts[1])
                if start > end:
                    raise ValueError("A > B")
            elif base.isdigit():
                start, end = int(base), int(base)
            else:
                raise ValueError("Invalid item")

            if '/' in item:
                if base == '*':
                    end = max_val
                elif '-' in base:
                    end = int(base.split('-', 1)[1])
                else:
                    end = max_val

            for v in range(start, end + 1, step):
                if v < min_val or v > max_val:
                    raise ValueError("Out of range")
                values.add(v)
        return values, is_star

    fields = expr.split()
    if len(fields) != 5:
        raise ValueError("Wrong number of fields")

    minutes_set, _ = parse_field(fields[0], 0, 59)
    hours_set, _ = parse_field(fields[1], 0, 23)
    doms_set, dom_star = parse_field(fields[2], 1, 31)
    months_set, _ = parse_field(fields[3], 1, 12)
    dows_raw, dow_star = parse_field(fields[4], 0, 7)
    dows_set = {(d - 1) % 7 for d in dows_raw}

    def matches_day(dt):
        dom_match = dt.day in doms_set
        dow_match = dt.weekday() in dows_set

        if not dom_star and not dow_star:
            return dom_match or dow_match
        else:
            return dom_match and dow_match

    current = after.replace(second=0, microsecond=0) + timedelta(minutes=1)
    limit = current + timedelta(days=3000)

    while current < limit:
        if current.month in months_set and matches_day(current):
            if current.hour in hours_set and current.minute in minutes_set:
                return current
        current += timedelta(minutes=1)

    raise ValueError("No match within 3000 days")
