    regex_parts = []
    for seg in segments:
        if seg == '**':
            regex_parts.append('.*')
        else:
            regex_parts.append(_segment_to_regex(seg))

    regex = '^' + '/'.join(regex_parts) + '$'
    return bool(re.fullmatch(regex, path))


